def _get_all_connection_axes(connections, facedim):
    all_axes = []
    for c in connections[facedim].values():
        all_axes.extend(list(c.keys()))
    # deduplicate while preserving order of first appearance: an unordered set
    # would make downstream processing order depend on the process hash seed
    return list(dict.fromkeys(all_axes))

